import {drawAssetMedia} from './effect-library.js?v=motion-v70';
import {villageDefaults} from './village-motion.js?v=motion-v70';
import {precisionDefaults,precisionState} from './precision-motion.js?v=motion-v70';
import {recordSceneAsset,alphaFor} from './scene-geometry.js?v=motion-v70';
const clamp=q=>Math.max(0,Math.min(1,q));const ease=q=>{q=clamp(q);return q*q*(3-2*q)};
function plate(c,im,scale,x,y,f={},age=0){const k=Math.max(960/im.naturalWidth,540/im.naturalHeight)*scale;drawAssetMedia(c,im,[480-im.naturalWidth*k/2+x,270-im.naturalHeight*k/2+y,im.naturalWidth*k,im.naturalHeight*k],f,age)}
function record(c,kind,name,rect=[0,0,960,540],alpha=null){recordSceneAsset(c,{id:kind,kind,name,assetSlot:kind},rect,alpha)}
export function paintExterior(c,s,input,images){const f={...villageDefaults,...precisionDefaults,...input},p=precisionState(s,f),customTown=/^(data:|blob:)/.test(images.villageTown?.src||'')&&!/^(data:|blob:)/.test(images.precisionArchitecture?.src||''),architecture=customTown?images.villageTown:images.precisionArchitecture;
 // Extend only the off-stage floor for the portal overscan; never stretch a row of portrait pixels.
 c.save();c.fillStyle='#414642';c.fillRect(-100,540,1160,540);c.strokeStyle='#292e2c';c.lineWidth=2;for(let row=0;row<12;row++)for(let col=-2;col<23;col++){const x=col*48+(row%2)*24,y=540+row*25;c.fillStyle=`rgb(${60+(row*17+col*11+999)%24},${64+(row*17+col*11+999)%24},${61+(row*17+col*11+999)%24})`;c.fillRect(x+2,y+2,44,21);c.strokeRect(x+2,y+2,44,21)}c.restore();
 const sky=c.createLinearGradient(0,0,0,430);sky.addColorStop(0,f.precisionSkyTop);sky.addColorStop(1,f.precisionSkyBottom);c.fillStyle=sky;c.fillRect(0,0,960,540);
 const cloud=images.precisionClouds;if(cloud?.naturalWidth){c.save();c.globalAlpha*=f.precisionCloudOpacity;const w=f.precisionCloudWidth,h=w*cloud.naturalHeight/cloud.naturalWidth,phase=((s.age*f.precisionCloudSpeed)%(w*.9)+w*.9)%(w*.9);for(let i=-2;i<=1;i++)drawAssetMedia(c,cloud,[i*w*.9+phase-w*.25,f.precisionCloudY,w,h*.72],f,s.age);c.restore()}
 if(architecture?.naturalWidth){c.save();c.filter=`brightness(${f.villageTownBrightness}) saturate(${f.villageSaturation}) blur(${f.villageTownBlur}px)`;plate(c,architecture,f.villageTownScale+s.town*f.precisionArchitecturePush,f.villageTownX+s.town*f.precisionArchitectureTravel,f.villageTownY,f,s.age);c.restore();record(c,customTown?'villageTown':'precisionArchitecture','Town buildings and depth')}
 if(s.boysExit<1){const im=images.villageBoys,progress=clamp(s.age/Math.max(.1,s.townAt)),exitX=f.villageBoysExitX===-90?f.precisionBoysExitX:f.villageBoysExitX,exitY=f.villageBoysExitY===650?f.precisionBoysExitY:f.villageBoysExitY,growth=f.villageBoysExitZoom===.5?f.precisionBoysExitZoom:f.villageBoysExitZoom,scale=1+s.window*f.precisionBoysEntryGrow+progress*f.villageBoysPush+s.boysExit*growth,w=f.villageBoysWidth*scale,h=w*im.naturalHeight/im.naturalWidth,x=f.villageBoysX+(1-s.window)*32+p.hold*f.precisionBoysDrift+(s.boysExit**f.precisionExitAccel)*exitX,y=f.villageBoysY+s.boysExit*exitY;
 c.save();c.globalAlpha*=f.villageBoysOpacity;c.filter=`saturate(${f.villageSaturation}) blur(${f.villageBoysBlur+(1-s.window)*2}px)`;drawAssetMedia(c,im,[x-w/2,y-h/2,w,h],f,s.age);c.restore();record(c,'villageBoys','Rudi and Adi',[x-w/2,y-h/2,w,h],alphaFor(im));
 c.save();c.globalAlpha*=p.names*f.villageBoysOpacity*(1-ease(s.boysExit*.8));c.translate(x,y);c.scale(scale,scale);c.font=`800 ${f.villageNameSize*f.precisionNameScale}px Arial, sans-serif`;c.textAlign='center';c.fillStyle=f.villageNameColor;c.shadowColor='#08101b';c.shadowBlur=4;for(const [text,nx]of [[f.villageLeftName,f.villageLeftNameX],[f.villageRightName,f.villageRightNameX]])c.fillText(text,nx-f.villageBoysX,f.villageNameY-f.villageBoysY);c.restore();
 }
 if(p.masonryClear<1&&images.precisionMasonry?.naturalWidth){const im=images.precisionMasonry,w=f.precisionMasonryWidth,h=w*im.naturalHeight/im.naturalWidth,x=-35-p.masonryClear*f.precisionMasonryTravel;c.save();c.globalAlpha*=f.precisionMasonryOpacity;c.filter='brightness(.8) saturate(.65)';drawAssetMedia(c,im,[x,f.precisionMasonryY,w,Math.max(540,h)],f,s.age);c.restore();record(c,'precisionMasonry','Near masonry passage',[x,f.precisionMasonryY,w,Math.max(540,h)],alphaFor(im))}
 return p;
}
